def autocorrelation(values: list[float], lag: int) -> float:

    n: int = len(values)
    mean: float = 0.0
    for v in values:
        mean += v
    mean = mean / n
    num: float = 0.0
    den: float = 0.0
    for i in range(n):
        den += (values[i] - mean) * (values[i] - mean)
        if i + lag < n:
            num += (values[i] - mean) * (values[i + lag] - mean)
    return num / den
